/// <summary> Получает или устанавливает категорию инструмента ["spot", "linear", "inverse", "option"] </summary>
/// <param name="_category"> Категория торговых инструментов </param>
/// <returns> Категория торговых инструментов </returns>
[DataMember('category')]
public str parmCategory(str _category = category)
{
    category = _category;
    return category;
}

/// <summary> Получает или устанавливает курсор для пагинации </summary>
/// <param name="_nextPageCursor"> Токен пагинации </param>
/// <returns> Токен пагинации </returns>
[DataMember('nextPageCursor')]
public str parmNextPageCursor(str _nextPageCursor = nextPageCursor)
{
    nextPageCursor = _nextPageCursor;
    return nextPageCursor;
}

/// <summary> Получает или устанавливает список инструментов </summary>
/// <param name="_list"> Список торговых инструментов </param>
/// <returns> Список торговых инструментов </returns>
[DataMember('list'), DataCollectionAttribute(Types::Class, classStr(RMarketJson_Bybit_Instrument_Item))]
public List parmList(List _list = list)
{
    list = _list;
    return list;
}
